# Meta: this is the classic LIS problem — DP on positions.
# Approach: dp[i] = LIS length ending at index i. For each i, scan earlier j<i with nums[j]<nums[i].
def length_of_lis(nums):
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)
```

