# Meta: stack-based bracket validation.
# Approach: push openers, pop on matching closer, reject on mismatch.
def is_valid_parens(s):
    pairs = {')':'(',']':'[','}':'{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack[-1] != pairs[c]: return False
            stack.pop()
    return not stack
```

