# Meta: hash-map complement lookup.
# Approach: as we scan, check if (target - x) was already seen.
def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []
