# Meta: sliding window with last-seen-index map.
# Approach: expand right, contract left past prior occurrence.
def length_of_longest_substring(s):
    seen = {}
    left = 0
    best = 0
    for right, c in enumerate(s):
        if c in seen and seen[c] >= left:
            left = seen[c] + 1
        seen[c] = right
        if right - left + 1 > best:
            best = right - left + 1
    return best
```

