# Meta: canonical-form grouping in a hash map.
# Approach: signature = sorted characters; group by signature.
def group_anagrams(strs):
    from collections import defaultdict
    g = defaultdict(list)
    for s in strs:
        g[''.join(sorted(s))].append(s)
    return list(g.values())
