# Meta: 2D DP on grid positions.
# Approach: dp[i][j] = dp[i-1][j] + dp[i][j-1]; first row/col are all 1.
def unique_paths(m, n):
    dp = [[1]*n for _ in range(m)]
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[m-1][n-1]
